def common_questions(band):
 return [
Q(1,band,'Start at +1 m. Walk 5 m left, then 3 m right. Find the final position, distance and displacement.',1,'Start +1 m; 5 m left, then 3 m right.', 'Position changes carry direction; path lengths do not.','Track the walk step by step: start at +1 m, walk 5 m left to reach 1 − 5, then walk 3 m right to reach the final position, 1 − 5 + 3. Distance simply adds both leg lengths, 5 + 3, while displacement compares only the final position to the start, −1 − (+1).','Final position −1 m; distance 8 m; displacement −2 m (left).','The final coordinate is not automatically the displacement.', ['Keep the starting coordinate separate from the lengths walked.','Mark the start, the turning point and the finish on a number line.','The turning point is at +1 − 5 m. Find the finish next.'],band+'-L3' if band=='B30' else band+'-L1',workspace='Start → turning point → finish\nFinal position: ____\nDistance: ____   Displacement: ____',numeric={'kind':'route','positions':[1,-4,-1],'distance':8,'displacement':-2}),
Q(2,band,'An object moves from −2 m to +5 m without reversing. Find its distance and displacement. Explain the signs.',0,'Move from −2 m to +5 m with no reversal.','The route goes 2 m to zero and another 5 m right.','Distance adds the two legs of the actual path travelled: 2 m to reach zero, then 5 m more to +5 m, giving 2 + 5. Displacement instead compares only the two endpoints, final position minus initial position: +5 − (−2).','Distance 7 m; displacement +7 m (right).','Equal distance and displacement size require no reversal in this straight-line journey.', ['Crossing the origin does not mean reversing direction.','Draw −2, 0 and +5 in order along the line.','The first part of the path, from −2 m to 0 m, is 2 m.'],band+'-L1',workspace='Sketch the line and explain why crossing zero is not a turn.',numeric={'kind':'route','positions':[-2,5],'distance':7,'displacement':7}),
Q(3,band,'Two students start at 0 m and finish at +4 m. Must they have travelled the same distance? Draw two journeys to support your answer.',0,'Same start 0 m and finish +4 m; compare possible distances.','Endpoints fix displacement but leave the path undecided.','One can go directly 0 → +4. Another can go 0 → +7 → +4. Their paths are 4 m and 7 + 3 m.','No. These distances are 4 m and 10 m; both displacements are +4 m.','A drawing can disprove an “always” claim.', ['The question fixes the endpoints, not the route.','Draw one direct route and one route with a turn.','For the turning route, choose a turning point beyond +4 m.'],band+'-L2' if band=='B30' else band+'-L1',task_type='Explain',workspace='Draw and label two routes. Keep the endpoints the same.'),
Q(4,band,'A student walks 7 m right and then 3 m left. Find distance and displacement, taking right as positive.',1,'Walk 7 m right, then 3 m left.','Both legs count towards distance, while leftward motion reduces the rightward change.','Both legs of the walk add to the total distance regardless of direction: 7 + 3. For displacement, keep the sign of each leg since right is positive; the rightward leg contributes +7 m and the leftward leg contributes −3 m, so add the signed changes.','Distance 10 m; displacement +4 m (right).','Separate total path from net change.', ['The student reverses direction after the first leg.','Use a path line and a separate start-to-finish arrow.','Add 7 m and 3 m to begin the distance calculation.'],band+'-L2' if band=='B30' else band+'-L1',numeric={'kind':'route','positions':[0,7,4],'distance':10,'displacement':4}),
Q(5,band,'An object moves at +5 m/s for 3 s, then at −2 m/s for 2 s. Find displacement and distance for the whole journey.',2,'Velocity +5 m/s for 3 s, then −2 m/s for 2 s.','Each interval has constant velocity, so its signed area is velocity × duration.','The changes are +5 × 3 = +15 m and −2 × 2 = −4 m. Add with signs for displacement; add sizes for distance.','Displacement +11 m; distance 19 m. Check: 19 ≥ 11.','Negative velocity gives negative displacement, not negative distance.', ['One interval is rightward and one is leftward.','Draw two velocity–time rectangles on opposite sides of zero.','The first signed area is (+5 m/s) × (3 s).'],band+'-L6' if band=='B30' else band+'-L2',numeric={'kind':'vt','segments':[[0,5,3,5],[3,-2,5,-2]],'distance':19,'displacement':11}),
Q(6,band,'Use the graph to find displacement and distance from 0 s to 5 s. Give a physical meaning for each area.',3,'Graph: +4 m/s from 0–2 s, then −2 m/s from 2–5 s.','Graph widths are durations. The second width is 5 − 2 = 3 s.','Signed areas are +4 × 2 = +8 m and −2 × 3 = −6 m. For distance count both path lengths.','Displacement +2 m; distance 14 m. The parts mean 8 m right and 6 m left.','Read each width from its endpoints before multiplying.', ['Read the duration of each horizontal segment.','Separate the two rectangular regions at t = 2 s.','For the first region, write (+4) × (2 − 0).'],band+'-L6' if band=='B30' else band+'-L2',fig=graph(band+'-A6-F',[[0,4,2,4],[2,-2,5,-2]]),numeric={'kind':'vt','segments':[[0,4,2,4],[2,-2,5,-2]],'distance':14,'displacement':2}),
Q(7,band,'A constant velocity of +2.5 m/s is shown from 0 s to 8 s. Find displacement and distance. Why do their sizes agree?',2,'Constant velocity +2.5 m/s from 0–8 s.','The graph is one positive rectangle; there is no reverse motion.','Signed area = (+2.5 m/s) × (8 s) = +20 m. The same area size is the path length.','Displacement +20 m; distance 20 m. Their sizes agree because direction does not reverse.','A constant positive velocity produces steadily increasing position.', ['The velocity stays on one side of zero.','Draw the rectangle and label height and width with units.','Write area = (+2.5 m/s) × (8 s).'],band+'-L5' if band=='B30' else band+'-L2',numeric={'kind':'vt','segments':[[0,2.5,8,2.5]],'distance':20,'displacement':20}),
Q(8,band,'A trolley has the velocity–time graph shown. Find displacement and distance from 0 s to 6 s. Explain why 6 × 6 is unsuitable.',3,'Velocity increases linearly from 0 to +6 m/s in 6 s.','The graph forms a triangle. The trolley does not spend all 6 s at its final velocity.','The triangle is half of a 6 s by 6 m/s rectangle: ½ × 6 × 6 = 18 m.','Displacement +18 m; distance 18 m. The graph never goes below zero.','Choose the shape from the actual graph, not just its final height.', ['The height grows during the interval.','Compare the region with the complete enclosing rectangle.','The rectangle would have area (6 s) × (6 m/s); use the fraction actually occupied.'],band+'-L7' if band=='B30' else band+'-L3',fig=graph(band+'-A8-F',[[0,0,6,6]]),task_type='Connect',numeric={'kind':'vt','segments':[[0,0,6,6]],'distance':18,'displacement':18})]
